<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, nextTick } from 'vue'
import { api, ApiError } from './api'
import { referencesFor, referenceLink, locatorLabel, roleLabel, shanghaiTime, actionLabel, previewComponentLabel, previewActionLabel, matchConsultation, savePersonalIntake, createConsultation, sendWithRecord, isCurrent } from './personalState'
import Settings from './Settings.vue'
import ConsultModelBar from './ConsultModelBar.vue'
import LocalDecision from './LocalDecision.vue'
import ConsultationAnalysis from './ConsultationAnalysis.vue'
import type {ModelSelection} from './personalState'
const access=ref<any>(null), loginPassword=ref(''), loginBusy=ref(false)
const browser=api.runtime.platform==='browser'
const tab=ref(browser?'formulas':'consult'), error=ref(''), notice=ref(''), overview=ref<any>({}), connected=ref(false)
const history=ref<any[]>([]), record=ref<any>(null), context=ref<any>({}), draft=ref(''), intake=ref<any>({}), intakeOpen=ref(false), busy=ref(false), job=ref<any>(null)
const sources=ref<any[]>([]), sourceId=ref(''), search=ref(''), searched=ref(false), results=ref<any[]>([]), unit=ref<any>(null), formulas=ref<any[]>([]), formulaQuery=ref(''), selectedFormula=ref<any>(null)
const excerptMode=computed(()=>browser&&sources.value.length>0&&sources.value.every((s:any)=>s.format==='excerpt'))
const excerptUnitCount=computed(()=>sources.value.reduce((n:number,s:any)=>n+(s.units||0),0))
const modelSelection=ref<ModelSelection|null>(null), modelRefresh=ref(0)
const standalone=computed(()=>access.value?.standalone===true||api.runtime.standalone)
const tabs=computed(()=>[
  {id:'consult',label:'书库问答'},
  {id:'library',label:'倪氏书库'},
  {id:'formulas',label:'经方速查'},
  {id:'settings',label:'模型与数据'},
])
const tabTitle=computed(()=>tabs.value.find(item=>item.id===tab.value)?.label||'倪氏经方')
const reloadPage=()=>window.location.reload()
const jobRunning=computed(()=>['queued','running'].includes(job.value?.status))
const fields=[['chief_complaint','主诉'],['duration','病程'],['tongue','舌象'],['pulse','脉象'],['sleep','睡眠'],['appetite','饮食'],['stool','大便'],['urine','小便'],['medical_history','既往病史'],['medications','现用药物'],['allergies','过敏情况'],['notes','其他补充']]
const listFields=[['body_locations','部位'],['pain_natures','疼痛性质'],['symptoms','伴随症状']]
const chips=['发热','怕冷','出汗','头痛','口渴','乏力','腹痛','恶心','咳嗽','失眠']
let timer:ReturnType<typeof setTimeout>|undefined
let unitRequest=0
let navigation=0
const unitPanel=ref<HTMLElement|null>(null)
const importing=ref(false), originalBusy=ref(false), originalDocument=ref('')
const importInput=ref<HTMLInputElement|null>(null)
let originalBlob=''
function clearOriginal(){if(originalBlob)URL.revokeObjectURL(originalBlob);originalBlob='';originalDocument.value=''}
async function importLibrary(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;importing.value=true;error.value='';try{const result=await api.importKnowledge(file);await loadSources();overview.value=await api.request('/personal/overview');if(record.value?.id)await loadRecord(record.value.id);notice.value=`书库已导入：${result.metadata?.sources??sources.value.length} 个来源，${result.metadata?.pdf_pages??overview.value.pdf_pages} 页原文。`}catch(e){error.value=message(e)}finally{importing.value=false;input.value=''}}
async function openOriginal(){const target=unit.value;if(!target?.original_url||originalBusy.value)return;originalBusy.value=true;try{const blob=await api.request<Blob>(target.original_url);if(unit.value!==target)return;clearOriginal();originalBlob=URL.createObjectURL(blob);originalDocument.value=originalBlob+(target.format==='pdf'?`#page=${target.unit_no}`:'')}finally{originalBusy.value=false}}
async function inspectFormula(id:string){selectedFormula.value=await api.request(`/formulas/${encodeURIComponent(id)}`);tab.value='formulas'}
function message(e:unknown){return e instanceof Error?e.message:String(e)}
async function run(fn:()=>Promise<void>){error.value='';notice.value='';try{await fn()}catch(e){error.value=message(e)}}
async function refreshHistory(){history.value=(await api.request<any>('/consultations')).items}
async function loadRecord(id:string){const [r,c]=await Promise.all([api.request<any>(`/consultations/${id}`),api.request<any>(`/consultations/${id}/context`)]);if(!isCurrent(id,record.value?.id))return;record.value=r;context.value=c;intake.value=structuredClone(r.intake||{})}
async function selectRecord(id:string){navigation++;if(timer)clearTimeout(timer);job.value=null;record.value={id,messages:[]};context.value={};await loadRecord(id)}
async function createRecord(snapshot?:any){const generation=++navigation;const r=await createConsultation(api,snapshot,()=>generation===navigation);if(!r){await refreshHistory();return null}record.value=r;context.value={};intake.value=structuredClone(r.intake||{});job.value=null;await refreshHistory();if(generation!==navigation)return null;await loadRecord(r.id);return generation===navigation?r:null}
async function saveIntake(){const updated=await savePersonalIntake(api,intake.value,record.value,snapshot=>createRecord(snapshot),()=>record.value);if(!updated)return;const id=updated.id;record.value=updated;intakeOpen.value=false;await loadRecord(id);await refreshHistory();notice.value='问诊单已保存。'}
async function poll(id:string, consultationId:string){const value=await api.request<any>(`/model/jobs/${id}`);if(!isCurrent(consultationId,record.value?.id))return;job.value=value;if(['queued','running'].includes(value.status))timer=setTimeout(()=>run(()=>poll(id,consultationId)),1000);else {await loadRecord(consultationId);await refreshHistory()}}
async function send(){if(!draft.value.trim()||busy.value||jobRunning.value)return;const selection=modelSelection.value&&{...modelSelection.value};if(!selection)throw Error('请先应用问诊模型配置');busy.value=true;const text=draft.value.trim();let id=record.value?.id,saved=false;try{const j=await sendWithRecord({post:async(path,data)=>{const result=await api.post<any>(path,data);if(path.includes('/messages')){saved=true;if(isCurrent(id,record.value?.id))draft.value=''}return result}},record.value,async()=>{const r=await createRecord();id=r?.id;return r},text,()=>record.value,selection);if(!j||!isCurrent(id,record.value?.id))return;job.value=j;await loadRecord(id);await poll(j.id,id)}catch(e){if(e instanceof ApiError&&e.status===409){modelSelection.value=null;modelRefresh.value++}if(saved&&isCurrent(id,record.value?.id))await loadRecord(id);throw e}finally{busy.value=false}}
async function cancel(){if(!job.value)return;await api.post(`/model/jobs/${job.value.id}/cancel`,{});await poll(job.value.id,record.value.id)}
async function loadSources(){sources.value=(await api.request<any>('/library/sources')).items}
async function searchLibrary(){const p=new URLSearchParams({q:search.value,limit:'100'});if(sourceId.value)p.set('source_id',sourceId.value);results.value=(await api.request<any>(`/library/search?${p}`)).items;searched.value=true}
async function openUnit(source:string,n:number){clearOriginal();const request=++unitRequest;const result=await api.request<any>(`/library/sources/${encodeURIComponent(source)}/units/${n}`);if(request===unitRequest){unit.value=result;await nextTick();if(unitPanel.value){unitPanel.value.scrollTop=0;if(window.matchMedia('(max-width: 850px)').matches)unitPanel.value.scrollIntoView({block:'start'})}}}
function viewLocalSource(value:{source:string;unit:number}){tab.value='library';void run(()=>openUnit(value.source,value.unit))}
async function confirmFact(value:{term:string;state:'present'|'absent'}){const id=record.value?.id;if(!id)return;const revision=record.value.revision;const saved=await api.post<any>(`/consultations/${encodeURIComponent(id)}/facts/confirm`,{...value,expected_revision:revision});if(!isCurrent(id,record.value?.id))return;record.value=saved;intake.value=structuredClone(saved.intake||{});await loadRecord(id);notice.value='当前体征已更新，方证分析已刷新。'}
async function loadFormulas(){formulas.value=(await api.request<any>(`/formulas?${new URLSearchParams({q:formulaQuery.value,limit:'30'})}`)).items}
async function match(){const id=record.value?.id;if(!id){notice.value='请先创建问诊记录。';return}const result=await matchConsultation(api,id,draft.value,()=>record.value?.id);if(!result)return;context.value=result.context;formulas.value=result.items;selectedFormula.value=null}
function toggleChip(chip:string){const a=intake.value.symptoms||[];intake.value.symptoms=a.includes(chip)?a.filter((v:string)=>v!==chip):[...a,chip]}
const loc=locatorLabel
function value(v:any){return v==null||v===''?'未提供':v}
async function init(){access.value=await api.session();if(access.value.authenticated===false)return;overview.value=await api.request('/personal/overview');connected.value=true;await Promise.all([refreshHistory(),loadSources(),loadFormulas()])}
function lock(){if(access.value)access.value.authenticated=false;if(timer)clearTimeout(timer)}
async function login(){loginBusy.value=true;try{await api.post('/access/login',{password:loginPassword.value});loginPassword.value='';await init()}finally{loginBusy.value=false}}
onMounted(()=>{api.onUnauthorized=lock;window.addEventListener('tcm-logout',lock);run(init)});onUnmounted(()=>{clearOriginal();api.dispose();if(timer)clearTimeout(timer);api.onUnauthorized=undefined;window.removeEventListener('tcm-logout',lock)})
</script>
<template><div v-if="!access || access.authenticated===false" class="access-screen"><section class="panel"><div class="personal-brand">倪氏经方 · 个人工作台</div><p v-if="!access">{{browser?'正在准备网页运行环境……':standalone?'正在准备本机资料……':'正在连接电脑服务……'}}</p><form v-else @submit.prevent="run(login)"><h1>登录工作台</h1><p>病历、书库和模型授权保存在{{standalone?'本设备':'电脑端'}}。</p><label>访问密码<input v-model="loginPassword" type="password" autocomplete="current-password" required maxlength="256"></label><button class="primary" :disabled="loginBusy || !loginPassword">{{loginBusy?'正在登录':'登录'}}</button></form><p v-if="error" class="error-box" role="alert">{{error}}</p><button v-if="browser && error" @click="reloadPage">重新加载页面</button><p v-if="!standalone && access && !access.access_configured" class="hint">请先在电脑本机网页设置访问密码，再启用局域网。</p></section></div><div v-else class="personal-shell"><aside class="personal-side"><div class="personal-brand"><span>倪</span><div>倪氏经方<small>个人书库</small></div></div><button class="new-button" @click="run(createRecord);tab='consult'">＋ 新建问诊</button><nav><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{item.label}}</button></nav><div class="history-title">历史记录</div><div class="history"><button v-for="r in history" :key="r.id" :class="{active:record?.id===r.id}" @click="tab='consult';run(()=>selectRecord(r.id))">{{r.title||'未命名问诊'}}<small>{{shanghaiTime(r.updated_at)}}</small></button><p v-if="!history.length">暂无记录</p></div><small class="side-foot">{{standalone?(connected?'● 本机资料已就绪':'○ 本机资料未就绪'):(connected?'● 本地服务已连接':'○ 本地服务未连接')}}</small></aside>
<main class="personal-main"><header class="personal-header"><div><small>PERSONAL CLASSIC LIBRARY</small><h1>{{tabTitle}}</h1><p v-if="browser" class="hint">公开网页版使用开源方剂索引。问诊记录与模型配置保存在当前浏览器，清除网站数据会删除本地记录和授权。</p><p v-else-if="standalone" class="hint">独立本机运行 · 本地资料和记录不自动跨端同步 · AI需联网</p></div><div class="overview"><template v-if="!browser">资料 {{overview.sources??'—'}} · 原书页 {{overview.pdf_pages??'—'}} · 文本单元 {{overview.text_units??'—'}} · </template>方剂 {{overview.formula_count??'—'}}</div></header>
<div v-if="error" class="error-box" role="alert">{{error}} <button class="text-link" @click="tab='settings'">前往设置</button></div><div v-if="notice" class="notice">{{notice}}</div>
<section v-show="tab==='consult'" class="consult-layout"><div class="hero" v-if="!record?.messages?.length"><div class="seal">經</div><h2>{{browser?(record?.title||'从四诊记录查经方'):'以经方为线索，与书库对话'}}</h2><p>{{browser?(record?.intake?.chief_complaint||'填写问诊单后可匹配方证。'):'记录症状与四诊信息，查阅原文、候选方证与 AI 推演。'}}</p><p v-if="browser&&record?.intake?.symptoms?.length">伴随症状：{{record.intake.symptoms.join('、')}}</p></div><div v-else class="conversation"><div class="section-head"><h2>{{record.title||'问诊记录'}}</h2><button class="text-link" @click="intakeOpen=true">编辑问诊单</button></div><article v-for="m in record.messages" :key="m.id" :class="['message',m.role]"><div class="message-label">{{m.role==='user'?'我的描述':'AI 推演'}} <span v-if="m.stale" class="warning"> · 旧结果，输入、来源或分析逻辑已变化</span></div><p v-if="m.role==='user'">{{m.text}}</p><template v-else-if="m.result"><p>{{m.result.summary}}</p><div v-if="m.result.questions?.length" class="result-card"><h3>进一步了解</h3><p v-for="q in m.result.questions" :key="q.key+q.question">{{q.question}} <small>{{q.reason}} · {{roleLabel(q.source_kind||'ai_inference')}}</small><span v-for="e in referencesFor(q.evidence_ids,m.evidence,context.evidence)" :key="e.id"> <a v-if="referenceLink(e).kind==='external'" :href="referenceLink(e).url" target="_blank" rel="noopener noreferrer">{{e.title}} · {{loc(e)}}</a><button v-else-if="referenceLink(e).kind==='unit'" class="text-link" @click="tab='library';run(()=>openUnit(e.source_id,e.unit_no))">{{e.title}} · {{loc(e)}}</button></span></p></div><div v-for="s in m.result.syndromes||[]" :key="s.name" class="result-card"><h3>候选证候 · {{s.name}}</h3><p>六经：{{value(s.six_meridian)}} · 八纲：{{value(s.eight_principles)}}</p><p>{{s.brief_reason}}</p><p>支持：{{s.supporting_symptoms?.join('、')||'未提供'}}；待了解：{{s.missing_information?.join('、')||'未提供'}}；反证：{{s.contradictions?.join('、')||'未提供'}}</p><p v-for="e in referencesFor(s.evidence_ids,m.evidence,context.evidence)" :key="e.id"><a v-if="referenceLink(e).kind==='external'" :href="referenceLink(e).url" target="_blank" rel="noopener noreferrer">{{e.title}} · {{loc(e)}}</a><button v-else-if="referenceLink(e).kind==='unit'" class="text-link" @click="tab='library';run(()=>openUnit(e.source_id,e.unit_no))">{{e.title}} · {{loc(e)}}</button><span v-else>{{e.title}} · {{loc(e)}}</span></p></div><div v-for="f in m.result.formulas||[]" :key="f.name" class="result-card"><h3>候选方 · {{f.name}}</h3><p class="hint">{{f.source_kind==='source_mapped'?'原件逐项映射（独立版本）':f.source_kind==='book_extraction'?'本次书证提取':f.source_kind==='book_reference'?'书证方名参考（未提取组成）':'经方速查目录'}}</p><p>{{f.reason}}</p><p>来源原量，非个人日剂量：<span v-for="c in f.components||[]" :key="c.name">{{c.name}} {{value(c.source_dose)}} {{c.source_unit||''}}；</span></p><p v-if="f.preparation">煎服参考（AI推演）：{{f.preparation}}</p><p v-for="(mod,i) in f.modifications||[]" :key="i">{{mod.application_status==='applied'?'差异预览已应用':'加减建议未应用'}}：{{actionLabel(mod.action)}} {{mod.herb}} {{mod.source_note}} {{mod.application_reason||''}}</p><details v-if="f.modification_preview"><summary>加减组成差异（非个人日剂量）</summary><p>预览组成：<span v-if="!f.modification_preview.components?.length">未提供</span><span v-for="(c,i) in f.modification_preview.components||[]" :key="i">{{previewComponentLabel(c)}}；</span></p><p v-for="(item,i) in f.modification_preview.applied||[]" :key="`a${i}`">已应用：{{previewActionLabel(item)}}</p><p v-for="(item,i) in f.modification_preview.unapplied||[]" :key="`u${i}`" class="warning">未应用：{{previewActionLabel(item)}}</p><p v-for="(item,i) in f.modification_preview.conflicts||[]" :key="`c${i}`" class="warning">冲突：{{item}}</p><p v-for="(item,i) in f.modification_preview.warnings||[]" :key="`w${i}`" class="hint">{{item}}</p></details><p v-for="e in referencesFor(f.evidence_ids,m.evidence,context.evidence)" :key="e.id"><a v-if="referenceLink(e).kind==='external'" :href="referenceLink(e).url" target="_blank" rel="noopener noreferrer">{{e.title}} · {{loc(e)}}</a><button v-else-if="referenceLink(e).kind==='unit'" class="text-link" @click="tab='library';run(()=>openUnit(e.source_id,e.unit_no))">{{e.title}} · {{loc(e)}}</button><span v-else>{{e.title}} · {{loc(e)}}</span></p></div><p v-if="m.result.risks?.length" class="warning">风险：{{m.result.risks.join('；')}}</p><p v-if="m.result.limitations?.length">限制：{{m.result.limitations.join('；')}}</p><div v-if="m.result.evidence_ids?.length" class="result-card"><h3>本次书证</h3><p v-for="e in referencesFor(m.result.evidence_ids,m.evidence,context.evidence)" :key="e.id"><strong>{{roleLabel(e.corpus_role)}} · {{e.title}} · {{loc(e)}}</strong><br>{{e.text}} <a v-if="referenceLink(e).kind==='external'" :href="referenceLink(e).url" target="_blank" rel="noopener noreferrer">查看固定来源</a><button v-else-if="referenceLink(e).kind==='unit'" class="text-link" @click="tab='library';run(()=>openUnit(e.source_id,e.unit_no))">查看原件</button></p><p class="hint">仅列出可在当前书证元数据中找到的引用；原典、讲解及 AI 推演分别以资料角色和上方推演标识。</p></div><p class="hint">历史来源优先显示该次冻结书证。</p></template><p v-else>{{m.text}}</p></article></div>
<div v-if="jobRunning" class="result-card"><strong>AI 正在推演……</strong><p class="hint">已提交模型请求，正在等待完整结构化结果；生成期间不显示半截 JSON，通常需要 10–60 秒。</p><button @click="run(cancel)">取消本次请求</button></div><div v-else-if="job && (!job.validated||job.stale||job.status==='failed'||job.status==='cancelled')" class="result-card"><strong>任务 {{job.status}}</strong><p v-if="job.stale" class="warning">基于旧输入或旧来源，仅供历史追溯。</p><pre v-if="job.text">{{job.text}}</pre><p v-if="job.error" class="warning">{{job.error}}</p></div><div v-if="job?.status==='completed' && job.validated" class="hint">检查范围：{{job.validation_scope ? JSON.stringify(job.validation_scope) : '结构与引用'}}；不代表医学正确。</div>
<div class="composer"><ConsultModelBar :key="modelRefresh" :active="tab==='consult'" :disabled="busy||jobRunning" @ready="modelSelection=$event" @settings="tab='settings'"/><textarea v-model="draft" rows="4" placeholder="描述你的症状，或向书库提出问题……"></textarea><div class="composer-actions"><button @click="intakeOpen=true">＋ 填写问诊单</button><button @click="run(match)">本地匹配经方</button><button class="primary" :disabled="busy||!draft.trim()||jobRunning||!modelSelection" @click="run(send)">{{jobRunning?'AI 正在推演……':'发送并请求 AI'}}</button></div><p class="hint">点击发送后先保存记录，再向已配置的服务发送必要症状和书证。未配置模型时仍可本地检索。</p></div><div v-if="context.formula_candidates?.length" class="result-card"><h3>本地候选线索</h3><p v-for="f in context.formula_candidates" :key="f.id">{{f.name}} · 支持 {{f.matched_features?.join('、')||'未提供'}} · 缺项 {{f.missing_features?.join('、')||'未提供'}} · 反证 {{f.contradictions?.join('、')||'未提供'}}</p></div><ConsultationAnalysis v-if="context.library_analysis" :analysis="context.library_analysis" :graph="context.decision_graph" :evidence="context.evidence" :revision="context.input_revision" @source="viewLocalSource" @formula="id=>run(()=>inspectFormula(id))" @fact="value=>run(()=>confirmFact(value))"/></section>
<section v-show="tab==='library'" class="library-grid library-reader"><div class="panel"><h2>资料检索</h2><div v-if="browser" class="result-card"><p v-if="excerptMode"><strong>当前为摘录模式</strong>：只检索网页内置的 {{sources.length}} 个来源、{{excerptUnitCount}} 个原文片段页，不是完整原文。完整页、PDF 原件和来源条件图需导入本地知识包。</p><p v-else>完整知识包已载入，可检索完整原文并阅读原件；无需手动导入。</p><input ref="importInput" type="file" accept=".zip,application/zip" hidden @change="importLibrary"><button :disabled="importing" @click="importInput?.click()">{{importing?'正在校验并导入书库……':'手动更新资料包'}}</button><p class="hint">资料已在首次打开时自动准备并缓存；仅在维护者发布新资料包时使用此入口。更新后可在右上角书籍下拉中看到完整来源。</p></div><template v-if="sources.length"><label>书籍<select v-model="sourceId"><option value="">全部资料</option><option v-for="s in sources" :key="s.id" :value="s.id">{{s.title}} · {{s.format}} · {{s.units}} 单元</option></select></label><div class="search-row"><input v-model="search" placeholder="搜索原文" @keyup.enter="run(searchLibrary)"><button @click="run(searchLibrary)">搜索</button></div><button v-for="r in results" :key="`${r.source_id}-${r.unit_no}`" class="search-result" @click="run(()=>openUnit(r.source_id,r.unit_no))"><strong>{{r.title}} · {{loc(r)}}</strong><small><template v-if="r.format==='excerpt'">摘录 · </template>{{r.snippet}}</small></button><p v-if="results.length" class="hint">显示 {{results.length}} 条{{results.length>=100?'（达到 100 条上限；请缩小检索词或用书籍下拉限定来源）':''}}</p><p v-if="!results.length" class="hint">{{searched?(excerptMode?'摘录中未找到该词；导入完整知识包可检索全书原文。':'未找到该词；可换用原文用字或选择其他书籍。'):'输入关键词检索书库。'}}</p></template><div v-else class="empty"><p>当前网页版尚未载入原文书库。已导入的课程 PDF 和原文资料可在本机工作台查阅。</p><button @click="tab='formulas'">查看经方速查</button></div></div><div ref="unitPanel" class="panel"><template v-if="unit"><h2>{{unit.title}}</h2><p class="hint">{{unit.format}} · {{loc(unit)}} · {{roleLabel(unit.corpus_role)}} {{unit.warning}}</p><p v-if="unit.original_url"><button v-if="browser" :disabled="originalBusy" @click="run(openOriginal)">{{originalBusy?'正在读取原件……':'打开原件'}}</button><a v-else :href="unit.original_url" target="_blank" rel="noopener">下载原件</a></p><template v-if="originalDocument"><a :href="originalDocument" target="_blank" rel="noopener">在新窗口打开原件</a><iframe v-if="unit.format==='pdf'" class="original-document" :src="originalDocument" :title="unit.title+'原件'"></iframe></template><p v-if="unit.source_url"><a :href="unit.source_url" target="_blank" rel="noopener">查看来源</a></p><h3>{{unit.content_scope==='extracted_quotes'?'已提取原文片段':'原始文字'}}</h3><template v-if="unit.content_scope==='extracted_quotes'&&unit.fragments?.length"><article v-for="(frag,fi) in unit.fragments" :key="frag.quote_sha256"><p class="hint">片段 {{fi+1}} · {{frag.quote_sha256.slice(0,12)}}</p><pre class="source-text">{{frag.text}}</pre></article><p class="hint">以上按来源片段分别展示，不是完整页；完整页需导入本地知识包。</p></template><pre v-else class="source-text">{{unit.raw_text||'未提供'}}</pre><template v-if="unit.ocr_text"><h3>OCR 草稿</h3><pre class="source-text">{{unit.ocr_text}}</pre></template><template v-if="unit.corrected_text"><h3>订正文字</h3><pre class="source-text">{{unit.corrected_text}}</pre></template><template v-if="unit.image_url"><h3>原件图像</h3><img class="original-page-image" :src="unit.image_url" alt="原件页面"></template></template><div v-else class="empty">{{sources.length?'选择检索结果阅读原文':'当前书库暂无可阅读的原文'}}</div></div></section>
<section v-show="tab==='formulas'" class="library-grid"><LocalDecision v-if="context.decision_graph" :graph="context.decision_graph" :evidence="context.evidence" :revision="context.input_revision" @source="viewLocalSource"/><div class="panel"><div class="search-row"><input v-model="formulaQuery" placeholder="搜索方名或证候" @keyup.enter="run(loadFormulas)"><button @click="run(loadFormulas)">搜索</button></div><button v-for="f in formulas" :key="f.id" class="search-result" @click="selectedFormula=f"><strong>{{f.name}}</strong><small>{{f.syndrome||'证候未提供'}} · {{f.six_meridian||'六经未提供'}}</small></button></div><div class="panel" v-if="selectedFormula"><h2>{{selectedFormula.name}}</h2><p>{{selectedFormula.syndrome||'证候未提供'}}</p><p>支持：{{selectedFormula.matched_features?.join('、')||'未提供'}}；缺项：{{selectedFormula.missing_features?.join('、')||'未提供'}}；反证：{{selectedFormula.contradictions?.join('、')||'未提供'}}</p><h3>组成 · 来源原量，非个人日剂量</h3><div v-for="c in selectedFormula.components||[]" :key="c.name"><p>{{c.name}} {{value(c.processing)}} · {{value(c.source_dose)}} {{c.source_unit||''}}</p><details v-if="c.source_ref"><summary>药味来源</summary><pre>{{c.source_ref}}</pre></details></div><h3>加减与注意</h3><p>{{value(selectedFormula.modification_notes)}}</p><p>{{value(selectedFormula.contraindications)}}</p><details v-if="selectedFormula.source_refs"><summary>来源详情</summary><pre>{{JSON.stringify(selectedFormula.source_refs,null,2)}}</pre></details></div></section>
<Settings v-if="tab==='settings'" />
<el-dialog v-model="intakeOpen" title="填写问诊单" width="min(760px, 95vw)"><p class="hint">留空表示未知，不代表没有该症状。</p><div class="intake-grid"><label>性别<select v-model="intake.sex"><option value="unknown">未提供</option><option value="female">女</option><option value="male">男</option></select></label><label>年龄<input v-model.number="intake.age_years" type="number" min="0" placeholder="未提供"></label><label v-for="field in fields" :key="field[0]">{{field[1]}}<input v-model="intake[field[0]]" placeholder="未提供"></label><label v-for="field in listFields" :key="field[0]">{{field[1]}}（以逗号分隔）<input :value="(intake[field[0]]||[]).join('、')" @input="intake[field[0]]=($event.target as HTMLInputElement).value.split(/[、,，]/).map(x=>x.trim()).filter(Boolean)"></label></div><div class="chip-row"><button v-for="chip in chips" :key="chip" :class="{selected:(intake.symptoms||[]).includes(chip)}" @click="toggleChip(chip)">{{chip}}</button></div><template #footer><button @click="intakeOpen=false">取消</button> <button class="primary" @click="run(saveIntake)">保存问诊单</button></template></el-dialog></main></div></template>

<style scoped>
.original-document{width:100%;height:70vh;min-height:500px;border:0}
</style>
